from __future__ import annotations

from html import escape
from typing import Any


def _e(value: Any) -> str:
    return escape(str(value if value is not None else ""), quote=True)


_STYLE = r"""
:root{color-scheme:light;--ink:#172033;--muted:#667085;--line:#dbe2ee;--panel:#fff;--soft:#f4f7fb;--brand:#2457d6;--warn:#9a6700;--bad:#b42318;--ok:#18794e;--purple:#6941c6}*{box-sizing:border-box}body{margin:0;background:#eef2f8;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans TC","PingFang TC",sans-serif;line-height:1.55}a{color:var(--brand);text-underline-offset:.16em}.hero{background:linear-gradient(135deg,#10275f,#244fc1 55%,#6f42c1);color:white;padding:28px max(18px,calc((100vw - 1220px)/2))}.hero h1{margin:0;font-size:clamp(1.7rem,4vw,2.8rem)}.hero p{margin:7px 0 0}.shell{width:min(1220px,calc(100% - 24px));margin:20px auto 60px}.notice{padding:13px 15px;background:#fff8db;border:1px solid #ecd887;border-radius:12px;color:#5d4a00}.toolbar{display:grid;grid-template-columns:minmax(260px,2fr) repeat(5,minmax(135px,1fr));gap:10px;padding:14px;background:white;border:1px solid var(--line);border-radius:14px;position:sticky;top:0;z-index:10}.field{display:grid;gap:5px}.field label{font-size:.76rem;color:var(--muted);font-weight:700}.field input,.field select{min-height:40px;border:1px solid #bfc9d9;border-radius:9px;background:white;padding:7px 9px}.wide{grid-column:span 2}.actions{grid-column:1/-1;display:flex;gap:8px;justify-content:flex-end;align-items:center;flex-wrap:wrap}.btn{border:1px solid #bfc9d9;background:white;border-radius:9px;min-height:36px;padding:6px 10px;cursor:pointer}.btn.primary{background:var(--brand);color:white;border-color:var(--brand)}.summary-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin:14px 0}.metric{background:white;border:1px solid var(--line);border-radius:12px;padding:10px 12px}.metric strong{display:block;font-size:1.25rem}.metric span{font-size:.78rem;color:var(--muted)}.result-bar,.pager{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:14px 2px}.paper-list{display:grid;gap:10px}.paper{background:white;border:1px solid var(--line);border-radius:14px;padding:16px;box-shadow:0 8px 24px rgba(24,37,68,.06)}.paper h2{font-size:1.07rem;line-height:1.38;margin:0}.original{color:var(--muted);font-size:.86rem;margin:6px 0 0}.badges{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.badge{display:inline-flex;padding:2px 8px;border-radius:999px;background:#edf2ff;color:#2346a5;font-size:.74rem;font-weight:750}.badge.fetch{background:#e8f6ef;color:var(--ok)}.badge.integrity{background:#ffebe9;color:var(--bad)}.badge.reserve{background:#fff3d6;color:var(--warn)}.badge.path{background:#f1eafe;color:var(--purple)}.score{font-size:1.2rem;font-weight:800}.reason{background:var(--soft);border-left:4px solid var(--brand);border-radius:8px;padding:9px 11px;font-size:.87rem}.meta{display:flex;gap:8px 14px;flex-wrap:wrap;margin-top:10px;color:var(--muted);font-size:.82rem}.links{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.links a,.links span{font-size:.78rem;border:1px solid #ccd5e3;background:white;border-radius:7px;padding:4px 7px;text-decoration:none}.empty{display:none;text-align:center;padding:28px;background:white;border:1px dashed #aeb9ca;border-radius:12px;color:var(--muted)}.empty.visible{display:block}.small{font-size:.78rem;color:var(--muted)}footer{text-align:center;padding:20px;color:var(--muted);font-size:.78rem}@media(max-width:1050px){.toolbar{position:static;grid-template-columns:1fr 1fr 1fr}.wide{grid-column:span 2}.summary-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.toolbar{grid-template-columns:1fr}.wide,.actions{grid-column:1}.summary-grid{grid-template-columns:1fr 1fr}}
"""

_SCRIPT = r"""
(() => {
  const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  const norm=v=>String(v||'').normalize('NFKC').toLocaleLowerCase('zh-Hant');
  const q=document.querySelector('#filter-query'),route=document.querySelector('#filter-route'),path=document.querySelector('#filter-path'),category=document.querySelector('#filter-category'),journal=document.querySelector('#filter-journal'),mode=document.querySelector('#filter-mode'),minimum=document.querySelector('#filter-score'),sort=document.querySelector('#filter-sort'),pageSize=document.querySelector('#page-size'),list=document.querySelector('#paper-list'),matched=document.querySelector('#matched-count'),pageLabel=document.querySelector('#page-label'),prev=document.querySelector('#page-prev'),next=document.querySelector('#page-next'),empty=document.querySelector('#empty-state'),reset=document.querySelector('#clear-filters'),error=document.querySelector('#load-error');
  let data=null,filtered=[],page=1;
  const routeLabel={INTEGRITY_REVIEW:'完整性維護',FETCH_CANDIDATE:'建議 fetch',RESERVE:'候補'};
  const badgeClass=v=>v==='INTEGRITY_REVIEW'?'integrity':v==='FETCH_CANDIDATE'?'fetch':'reserve';
  const option=(value,label)=>`<option value="${esc(value)}">${esc(label)}</option>`;
  const external=a=>(a.source_urls||[])[0]||'';
  const ids=a=>{const x=a.identifiers||{};return [x.doi?`<a href="https://doi.org/${esc(x.doi)}">DOI</a>`:'',x.pmid?`<a href="https://pubmed.ncbi.nlm.nih.gov/${esc(x.pmid)}/">PMID</a>`:'',x.pmcid?`<a href="https://pmc.ncbi.nlm.nih.gov/articles/${esc(x.pmcid)}/">PMCID</a>`:''].filter(Boolean).join('')};
  const card=a=>{const title=a.title_zh_tw||a.title_original;const original=a.title_zh_tw?`<p class="original"><strong>原文：</strong>${esc(a.title_original)}</p>`:'';const reasons=(a.reason_codes||[]).join(' · ');const authors=(a.authors||[]).slice(0,8).join('、')+((a.authors||[]).length>8?' 等':'');return `<article class="paper"><h2>${esc(title)}</h2>${original}<div class="badges"><span class="badge ${badgeClass(a.route)}">${esc(routeLabel[a.route]||a.route)}</span><span class="badge path">${esc(a.primary_path)}</span><span class="badge">${esc(a.processing_mode)}</span><span class="score">${esc(a.score)}</span></div><div class="reason"><strong>metadata 理由：</strong>${esc(reasons||'無')}<br><span class="small">未讀摘要／全文；此分數不是品質、創新性或證據力。</span></div><div class="meta"><span>${esc(a.journal)}</span><span>${esc(a.publication_date||'')}</span><span>${esc(authors||'作者未列出')}</span><span>${esc(a.canonical_id||'')}</span></div><div class="links"><a href="${esc(a.edition_url)}">edition</a><a href="${esc(a.canonical_json_url)}">完整 canonical JSON</a><a href="${esc(a.edition_url)}triage.json">全期 triage audit</a>${external(a)?`<a href="${esc(external(a))}">來源頁</a>`:''}${ids(a)||'<span>無標準識別碼</span>'}</div></article>`};
  function fill(id,values,labelFn=x=>x){const el=document.querySelector(id);for(const value of values)el.insertAdjacentHTML('beforeend',option(value,labelFn(value)))}
  function apply(resetPage=true){if(!data)return;const needle=norm(q.value).trim(),wantedRoute=route.value,wantedPath=path.value,wantedCategory=category.value,wantedJournal=journal.value,wantedMode=mode.value,min=Number(minimum.value)||0;filtered=(data.items||[]).filter(a=>(!needle||norm([a.title_zh_tw,a.title_original,a.journal,(a.authors||[]).join(' '),a.canonical_id,JSON.stringify(a.identifiers||{})].join(' ')).includes(needle))&&(!wantedRoute||(wantedRoute==='ACTIONABLE'?['INTEGRITY_REVIEW','FETCH_CANDIDATE'].includes(a.route):a.route===wantedRoute))&&(!wantedPath||a.primary_path===wantedPath)&&(!wantedCategory||(a.categories||[]).includes(wantedCategory))&&(!wantedJournal||a.journal_slug===wantedJournal)&&(!wantedMode||a.processing_mode===wantedMode)&&Number(a.score)>=min);filtered.sort((a,b)=>sort.value==='newest'?String(b.publication_date).localeCompare(String(a.publication_date))||Number(b.score)-Number(a.score):sort.value==='journal'?String(a.journal).localeCompare(String(b.journal))||Number(b.score)-Number(a.score):Number(b.score)-Number(a.score)||String(a.journal).localeCompare(String(b.journal)));if(resetPage)page=1;render()}
  function render(){const size=Number(pageSize.value)||50,totalPages=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,totalPages);const start=(page-1)*size,end=Math.min(start+size,filtered.length),slice=filtered.slice(start,end);list.innerHTML=slice.map(card).join('');matched.textContent=String(filtered.length);pageLabel.textContent=filtered.length?`${start+1}–${end} / ${filtered.length} · 第 ${page}/${totalPages} 頁`:'0 / 0';prev.disabled=page<=1;next.disabled=page>=totalPages;empty.classList.toggle('visible',filtered.length===0)}
  fetch('prefetch-triage-index.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(String(r.status));return r.json()}).then(v=>{data=v;const items=data.items||[];fill('#filter-path',[...new Set(items.map(x=>x.primary_path).filter(Boolean))].sort());fill('#filter-category',[...new Set(items.flatMap(x=>x.categories||[]))].sort());const journalSelect=document.querySelector('#filter-journal');journalSelect.innerHTML='<option value="">全部期刊</option>'+[...new Map(items.map(x=>[x.journal_slug,x.journal])).entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]))).map(([slug,name])=>option(slug,name)).join('');route.value='ACTIONABLE';apply(true)}).catch(()=>{error.hidden=false});
  for(const el of [q,route,path,category,journal,mode,minimum,sort,pageSize])el.addEventListener(el===q?'input':'change',()=>apply(true));
  prev.addEventListener('click',()=>{page=Math.max(1,page-1);render()});next.addEventListener('click',()=>{page+=1;render()});reset.addEventListener('click',()=>{q.value='';route.value='ACTIONABLE';path.value='';category.value='';journal.value='';mode.value='';minimum.value='0';sort.value='score';pageSize.value='50';apply(true)});
})();
"""


def render_prefetch_triage_page(index: dict[str, Any]) -> str:
    counts = index.get("counts") or {}
    return f"""<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="EvidenceRadar Editions metadata 預抓候選"><title>預抓候選｜EvidenceRadar Editions</title><style>{_STYLE}</style></head><body><header class="hero"><h1>Metadata 預抓候選</h1><p>從目前 canonical editions 全量題名與書目資料，建立可稽核的 fetch queue；沒有讀取摘要或全文。</p></header><main class="shell"><p><a href="./">← 返回期刊總表</a></p><p class="notice"><strong>先別把它當研究排名。</strong> `FETCH_CANDIDATE` 只表示題名／metadata 出現可操作訊號；`INTEGRITY_REVIEW` 是撤稿、關切或勘誤維護。分數不代表品質、效果大小、創新性或證據可信度。</p><section class="summary-grid"><div class="metric"><strong>{_e(counts.get('canonical_article_count',0))}</strong><span>canonical metadata</span></div><div class="metric"><strong>{_e(counts.get('actionable_count',0))}</strong><span>目前要處理</span></div><div class="metric"><strong>{_e(counts.get('fetch_candidate_count',0))}</strong><span>建議 fetch</span></div><div class="metric"><strong>{_e(counts.get('integrity_review_count',0))}</strong><span>完整性維護</span></div><div class="metric"><strong>{_e(counts.get('reserve_count',0))}</strong><span>候補</span></div><div class="metric"><strong>{_e(counts.get('catalog_only_count',0))}</strong><span>只留 catalog</span></div></section><section class="toolbar"><div class="field wide"><label for="filter-query">搜尋題名、作者、DOI／PMID</label><input id="filter-query" type="search" placeholder="輸入關鍵字…"></div><div class="field"><label for="filter-route">處理路徑</label><select id="filter-route"><option value="ACTIONABLE">目前要處理</option><option value="FETCH_CANDIDATE">建議 fetch</option><option value="INTEGRITY_REVIEW">完整性維護</option><option value="RESERVE">候補</option><option value="">候選＋候補全部</option></select></div><div class="field"><label for="filter-path">主要理由</label><select id="filter-path"><option value="">全部理由</option></select></div><div class="field"><label for="filter-category">領域</label><select id="filter-category"><option value="">全部領域</option></select></div><div class="field"><label for="filter-journal">期刊</label><select id="filter-journal"><option value="">全部期刊</option></select></div><div class="field"><label for="filter-mode">期刊模式</label><select id="filter-mode"><option value="">全部模式</option><option>FULL</option><option>TRIAGE</option><option>INDEX_ONLY</option><option>SUSPENDED</option></select></div><div class="field"><label for="filter-score">最低分</label><select id="filter-score"><option value="0">不限</option><option value="65">65</option><option value="80">80</option><option value="90">90</option><option value="92">92</option></select></div><div class="actions"><div class="field"><label for="filter-sort">排序</label><select id="filter-sort"><option value="score">分數</option><option value="newest">日期</option><option value="journal">期刊</option></select></div><div class="field"><label for="page-size">每頁</label><select id="page-size"><option>25</option><option selected>50</option><option>100</option><option>200</option></select></div><button class="btn primary" id="clear-filters" type="button">重設</button></div></section><div class="result-bar"><span>符合條件 <strong id="matched-count">0</strong> 筆</span><span><a href="prefetch-triage-index.json">triage index JSON</a> · <a href="prefetch-triage-policy.json">policy JSON</a></span></div><p id="load-error" class="notice" hidden>triage index 載入失敗，請直接開啟 JSON。</p><section id="paper-list" class="paper-list" aria-live="polite"></section><div id="empty-state" class="empty">沒有紀錄符合目前篩選。</div><div class="pager"><button class="btn" id="page-prev" type="button">上一頁</button><strong id="page-label">0 / 0</strong><button class="btn" id="page-next" type="button">下一頁</button></div><p class="small">全量判定可在各 edition 的 `triage.json` 稽核；根目錄 index 只載入完整性維護、fetch candidates 與 reserve，避免再把 catalog-only 內容灌回瀏覽 payload。</p></main><footer>EvidenceRadar Editions · deterministic metadata pre-fetch triage</footer><script>{_SCRIPT}</script></body></html>\n"""
